"use client";

import * as React from "react";
import { zipSync, strToU8 } from "fflate";
import { articleDocument } from "@creatoros/contract";
import { Button } from "@/components/ui/button";
import { client } from "@/lib/contract-client";
import {NativeEditorSurface,type NativeEditorHandle} from "@/features/reference-editors/native-editor-surface";
import {uploadEditorMedia} from "@/features/reference-editors/reference-editor-media";
import { parseArticleMarkdown, serializeArticleMarkdown, type MarkdownSection } from "./doocs-markdown";

type ArticleDocument = import("@creatoros/contract").ArticleDocument;
type Props = {
  accountId: string;
  outputId: string;
  sourceVersionId: string;
  value: ArticleDocument;
  savedDocument: ArticleDocument;
  onChange: (document: ArticleDocument) => void;
  onSave: (document: ArticleDocument) => Promise<boolean>;
};
type EditorValue = {markdown?: string; layout?: unknown; html?: string; error?: string; bindings?: Array<{key: string; url: string}>};
type StoredCheckpoint = { accountId: string; outputId: string; sourceVersionId: string; updatedAt: number; document: ArticleDocument; markdown: string; layout?: ArticleDocument["nativeLayout"] };

const frameClient = client as unknown as {
  getAssetFileDownloadUrl(input: { params: { assetId: string; assetFileId: string }; query: undefined; body: undefined }): Promise<{ url: string; fileName: string }>;
};
function sessionId(): string { return crypto.randomUUID(); }
function checkpointKey(accountId: string, outputId: string): string { return `creatoros:article:draft:${accountId}:${outputId}`; }
function sectionsForEditor(document: ArticleDocument): MarkdownSection[] {
  return document.sections.map((section) => ({ ...section, headingLevel: section.headingLevel ?? 2,
    body: [section.body, ...document.imageUses.filter((image) => image.sectionId === section.sectionId)
      .filter((image) => !section.body.includes(`creatoros-asset:${image.assetId}:${image.assetFileId}`))
      .map((image) => `<img src="creatoros-asset:${image.assetId}:${image.assetFileId}" alt="文章配图" />`)].filter(Boolean).join("\n\n"),
  }));
}

export function DoocsArticleEditor(props:Props){return <DoocsEditorSession key={`${props.accountId}:${props.outputId}:${props.sourceVersionId}`} {...props}/>;}
function DoocsEditorSession({ accountId, outputId, sourceVersionId, value, savedDocument, onChange, onSave }: Props) {
  const editorRef = React.useRef<NativeEditorHandle>(null);
  const alive=React.useRef(true),loadSequence=React.useRef(0),controller=React.useRef<AbortController|null>(null);
  const imported=React.useRef(new Map<string,{assetId:string;assetFileId:string}>());
  const session = React.useRef(sessionId());
  const [frameReady, setFrameReady] = React.useState(false);
  const [draftMarkdown, setDraftMarkdown] = React.useState(() => serializeArticleMarkdown(sectionsForEditor(value)));
  const [draftLayout, setDraftLayout] = React.useState<ArticleDocument["nativeLayout"]>(value.nativeLayout?.editor==="doocs-md"?value.nativeLayout:undefined);
  const [checkpoint, setCheckpoint] = React.useState<StoredCheckpoint | null>(null);
  const [checkpointConflict, setCheckpointConflict] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const [status, setStatus] = React.useState("Doocs 公众号编辑器尚未连接。");
  const structureFingerprint = JSON.stringify([value.sections.map((section) => [section.sectionId, section.order]), value.imageUses.map((image) => [image.sectionId, image.assetId, image.assetFileId])]);
  const priorStructure = React.useRef(structureFingerprint);
  const currentDocuments=React.useRef({value,savedDocument});
  React.useLayoutEffect(()=>{currentDocuments.current={value,savedDocument};});

  React.useEffect(() => {
    const raw = sessionStorage.getItem(checkpointKey(accountId, outputId));
    if (!raw) return;
    try {
      const saved = JSON.parse(raw) as StoredCheckpoint;
      if (saved.accountId !== accountId || saved.outputId !== outputId || Date.now() - saved.updatedAt > 24 * 60 * 60 * 1000) {
        sessionStorage.removeItem(checkpointKey(accountId, outputId)); return;
      }
      const parsed = articleDocument.safeParse(saved.document);
      if (!parsed.success) { sessionStorage.removeItem(checkpointKey(accountId, outputId)); return; }
      setCheckpoint({ ...saved, document: parsed.data, markdown: typeof saved.markdown === "string" ? saved.markdown : serializeArticleMarkdown(sectionsForEditor(parsed.data)) });
      const stale = saved.sourceVersionId !== sourceVersionId;
      if (!stale && typeof saved.markdown === "string") setDraftMarkdown(saved.markdown);
      if (!stale) setDraftLayout(saved.layout);
      setCheckpointConflict(stale);
    } catch { sessionStorage.removeItem(checkpointKey(accountId, outputId)); }
  }, [accountId, outputId, sourceVersionId]);

  const send = React.useCallback((type: string, body: Record<string, unknown> = {}) => {
    const operation=type==='init'||type==='set-document'?'load':type;
    const active=editorRef.current;if(!active)return Promise.reject(new Error('编辑器尚未准备好'));
    return active.request<EditorValue>(operation,body).catch(reason=>{if(alive.current)setError(reason instanceof Error?reason.message:'编辑未完成');throw reason;});
  }, []);

  const initializeFrame = React.useCallback(async () => {
    const active=editorRef.current;if(!active||!alive.current)return;
    controller.current?.abort();const abort=new AbortController();controller.current=abort;const generation=++loadSequence.current;
    const currentSession = session.current;
    const nonce = sessionId();
    const sections = sectionsForEditor(value);
    const markdown = serializeArticleMarkdown(sections);
    setDraftMarkdown(markdown); setDraftLayout(value.nativeLayout?.editor==="doocs-md"?value.nativeLayout:undefined);
    await send("init", { nonce, document: { title: value.title, markdown, layout: value.nativeLayout?.editor==="doocs-md"?value.nativeLayout:null } });
    abort.signal.throwIfAborted();
    try {
      for (const image of value.imageUses) {
        const link = await frameClient.getAssetFileDownloadUrl({ params: { assetId: image.assetId, assetFileId: image.assetFileId }, query: undefined, body: undefined });
        abort.signal.throwIfAborted();
        const response = await fetch(link.url, { credentials: "omit",signal:abort.signal });
        const contentType = response.headers.get("content-type") ?? "";
        const contentLength = Number(response.headers.get("content-length") ?? 0);
        if (!response.ok || !contentType.startsWith("image/") || contentLength > 25 * 1024 * 1024) throw new Error("素材图片无法安全读取。");
        const blob = await response.blob();
        if (!blob.type.startsWith("image/") || blob.size > 25 * 1024 * 1024) throw new Error("素材图片超过 25 MiB 或不是图片文件。");
        if (currentSession !== session.current||generation!==loadSequence.current||!alive.current||editorRef.current!==active) return;
        await send("asset", { assetId: image.assetId, assetFileId: image.assetFileId, blob });
      }
    } catch (reason) { if (currentSession === session.current&&!abort.signal.aborted&&alive.current) setError(reason instanceof Error ? reason.message : "素材图片预览不可用。"); }
  }, [send, value]);

  function receiveChanged(eventValue:unknown){
    if(!alive.current||!eventValue||typeof eventValue!=="object")return;
    const message=eventValue as EditorValue;
      if (typeof message.markdown === "string") {
        setDraftMarkdown(message.markdown); setDraftLayout(message.layout as typeof draftLayout);
        try {
          const parsed = parseArticleMarkdown(message.markdown, sectionsForEditor(value));
          const next = articleDocument.parse({ ...value, sections: parsed.sections,
            imageUses: parsed.imageRefs.map((image) => {
              const found = value.imageUses.find((item) => item.sectionId === image.sectionId && item.assetId === image.assetId && item.assetFileId === image.assetFileId);
              if(found)return found;
              const registered=imported.current.get(`${image.assetId}:${image.assetFileId}`);
              if(!registered)throw new Error("正文引用的素材已变化；请从 CreatorOS 素材库重新插入图片。");
              return {...registered,sectionId:image.sectionId,sourceKind:'existing' as const,reviewState:'selected' as const};
            }), nativeLayout: message.layout ?? undefined });
          onChange(next); setError(null); setStatus("修改已在本标签页暂存，尚未保存为正式版本。");
        } catch (reason) { setError(reason instanceof Error ? reason.message : "文章正文无法安全解析。"); }
      }
  }

  React.useEffect(() => {
    if (!frameReady||checkpoint) return;
    const timer = window.setTimeout(() => {
      try { sessionStorage.setItem(checkpointKey(accountId, outputId), JSON.stringify({ accountId, outputId, sourceVersionId, updatedAt: Date.now(), document: value, markdown: draftMarkdown, layout: draftLayout } satisfies StoredCheckpoint)); }
      catch { setStatus("未保存草稿仍在编辑器内存中；浏览器刷新后无法恢复。"); }
    }, 500);
    return () => clearTimeout(timer);
  }, [accountId, outputId, sourceVersionId, value, draftMarkdown, draftLayout, frameReady,checkpoint]);

  React.useEffect(()=>{alive.current=true;return()=>{alive.current=false;session.current=sessionId();loadSequence.current++;controller.current?.abort();imported.current.clear();};},[]);

  React.useEffect(() => {
    if (priorStructure.current === structureFingerprint) return;
    priorStructure.current = structureFingerprint;
    if (!frameReady) return;
    const sections = sectionsForEditor(value);
    const markdown = serializeArticleMarkdown(sections);
    setDraftMarkdown(markdown);
    void send("set-document", { document: { title: value.title, markdown, layout: value.nativeLayout?.editor==="doocs-md"?value.nativeLayout:null } }).catch(()=>undefined);
  }, [structureFingerprint, frameReady, send, value]);

  function restoreCheckpoint() {
    if (!checkpoint || checkpointConflict) return;
    onChange(checkpoint.document);
    const markdown = checkpoint.markdown;
    setDraftMarkdown(markdown); setDraftLayout(checkpoint.layout);
    void send("set-document", { document: { title: checkpoint.document.title, markdown, layout: checkpoint.layout ?? null } }).catch(()=>undefined);
    setCheckpoint(null);
  }

  async function saveEditorDraft() {
    if (busy || !frameReady || checkpointConflict) return;
    setBusy(true); setError(null);
    try {
      const parsed = parseArticleMarkdown(draftMarkdown, sectionsForEditor(value));
      const next = articleDocument.parse({ ...value, sections: parsed.sections,
        imageUses: parsed.imageRefs.map((image) => {
          const found = value.imageUses.find((item) => item.sectionId === image.sectionId && item.assetId === image.assetId && item.assetFileId === image.assetFileId);
          if(found)return found;
          const registered=imported.current.get(`${image.assetId}:${image.assetFileId}`);
          if(!registered)throw new Error("无法将未知素材加入正式文章，请重新从 CreatorOS 素材库插入。");
          return {...registered,sectionId:image.sectionId,sourceKind:'existing' as const,reviewState:'selected' as const};
        }), nativeLayout: draftLayout ?? undefined });
      if (await onSave(next)) { sessionStorage.removeItem(checkpointKey(accountId, outputId)); setCheckpoint(null); setStatus("正文与排版已保存并读回正式版本。"); }
    } catch (reason) { setError(reason instanceof Error ? reason.message : "文章保存未完成。"); }
    finally { if(alive.current)setBusy(false); }
  }

  async function exportFormalVersion() {
    if (busy || !frameReady || JSON.stringify(value) !== JSON.stringify(savedDocument)) {
      setError("请先保存并读回当前稿件，再导出公众号物料。"); return;
    }
    setBusy(true); setError(null);
    try {
      const active=editorRef.current;if(!active)throw new Error('编辑器尚未准备好');
      const frozen=JSON.stringify(savedDocument);
      const rendered=await active.request<EditorValue>('export-html');
      if(!alive.current||editorRef.current!==active||frozen!==JSON.stringify(currentDocuments.current.savedDocument)||frozen!==JSON.stringify(currentDocuments.current.value))throw new Error('稿件已改变，请重新导出');
      if (rendered.error) throw new Error(rendered.error);
      if (typeof rendered.html !== "string" || !Array.isArray(rendered.bindings)) throw new Error("编辑器没有返回可导出的 HTML。");
      const files: Record<string, Uint8Array> = {};
      const bindingPaths = new Map<string, string>();
      for (const [index, image] of savedDocument.imageUses.entries()) {
        const bindingKey = `${image.assetId}:${image.assetFileId}`;
        const binding = rendered.bindings.find((item) => item.key === bindingKey);
        if (!binding) throw new Error(`缺少段落 ${image.sectionId} 的图片绑定，导出已停止。`);
        const download = await frameClient.getAssetFileDownloadUrl({ params: { assetId: image.assetId, assetFileId: image.assetFileId }, query: undefined, body: undefined });
        const imageResponse = await fetch(download.url, { credentials: "omit" });
        const contentType = imageResponse.headers.get("content-type") ?? "";
        if (!imageResponse.ok || !contentType.startsWith("image/")) throw new Error(`无法下载公众号正文图片「${download.fileName}」，导出未生成。`);
        const imageBlob = await imageResponse.blob();
        if (!imageBlob.type.startsWith("image/") || imageBlob.size > 25 * 1024 * 1024) throw new Error("导出图片不是受支持的图片文件或超过 25 MiB。");
        const ext = download.fileName.match(/\.([a-z0-9]{2,5})$/i)?.[1]?.toLowerCase() ?? (imageBlob.type === "image/jpeg" ? "jpg" : "png");
        const relativePath = `assets/image-${String(index + 1).padStart(2, "0")}.${ext}`;
        bindingPaths.set(binding.url, relativePath);
        files[relativePath] = new Uint8Array(await imageBlob.arrayBuffer());
      }
      const safeTitle = savedDocument.title.replace(/[\\/:*?"<>|\u0000-\u001f]/g, "_").slice(0, 80) || "公众号文章";
      const content = rendered.html.replace(/src=(['"])(blob:[^'"]+)\1/g, (_match, quote: string, url: string) => {
        const path = bindingPaths.get(url);
        if (!path) throw new Error("公众号预览存在未绑定图片，导出已停止。");
        return `src=${quote}${path}${quote}`;
      });
      files["index.html"] = strToU8(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${safeTitle}</title></head><body><article>${content}</article></body></html>`);
      files["manifest.json"] = strToU8(JSON.stringify({ outputId, versionId: sourceVersionId, title: safeTitle, imageOrder: [...bindingPaths.values()], layout: savedDocument.nativeLayout ? "saved" : "base-theme", generatedAt: new Date().toISOString() }, null, 2));
      if(!alive.current||frozen!==JSON.stringify(currentDocuments.current.savedDocument)||frozen!==JSON.stringify(currentDocuments.current.value))throw new Error('稿件已改变，请重新导出');
      const archive = zipSync(files, { level: 6 });
      const url = URL.createObjectURL(new Blob([new Uint8Array(archive).buffer as ArrayBuffer], { type: "application/zip" }));
      const anchor = document.createElement("a"); anchor.href = url; anchor.download = `${safeTitle}-公众号物料.zip`; anchor.click();
      window.setTimeout(() => URL.revokeObjectURL(url), 1000);
      setStatus("已导出当前正式版本的 HTML 与图片 ZIP；请解压后用相对路径检查图片。");
    } catch (reason) { setError(reason instanceof Error ? reason.message : "公众号导出未完成。"); }
    finally { if(alive.current)setBusy(false); }
  }

  return <section className="space-y-3 rounded-xl border p-4">
    <div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="font-medium">公众号排版编辑器</h3><p className="text-xs text-muted-foreground">{status}</p></div>
      <div className="flex gap-2"><Button variant="outline" onClick={() => void exportFormalVersion()} disabled={busy || !frameReady || JSON.stringify(value) !== JSON.stringify(savedDocument)}>导出 HTML + 图片 ZIP</Button>
        <Button onClick={() => void saveEditorDraft()} disabled={busy || !frameReady || checkpointConflict}>{busy ? "处理中…" : "保存正文与排版"}</Button></div></div>
    {error && <p role="alert" className="rounded-md bg-red-50 p-2 text-sm text-red-700">{error}</p>}
    {checkpoint && <div role="status" className="rounded-md border border-amber-300 bg-amber-50 p-3 text-sm">
      {checkpointConflict ? <><span>标签页保存了旧版本草稿。当前正式稿已变化，请比较内容；旧草稿只读，不可直接覆盖当前版本。</span>
        <details className="mt-2"><summary className="cursor-pointer">查看旧草稿</summary><p className="mt-2 font-medium">{checkpoint.document.title}</p><pre className="mt-2 max-h-56 overflow-auto whitespace-pre-wrap rounded bg-white p-2">{checkpoint.markdown}</pre></details></> : "发现此标签页上次未保存的草稿。"}
      {!checkpointConflict && <Button className="ml-3" size="sm" variant="outline" onClick={restoreCheckpoint}>恢复未保存草稿</Button>}
      <Button className="ml-2" size="sm" variant="ghost" onClick={() => { sessionStorage.removeItem(checkpointKey(accountId, outputId)); setCheckpoint(null); setCheckpointConflict(false); }}>放弃旧草稿并继续当前稿</Button>
    </div>}
    <div className="h-[700px] min-h-0 overflow-hidden rounded-md border bg-surface"><NativeEditorSurface ref={editorRef} editor="doocs-md" owner={{accountId,outputId,sourceVersionId}} disabled={busy} onReady={()=>{setFrameReady(true);void initializeFrame().catch(reason=>{if(alive.current)setError(reason.message);});}} onChanged={receiveChanged} onError={setError} onImport={async file=>{
      const output=await client.getOutput({params:{outputId},query:undefined,body:undefined});if(!alive.current)throw new Error('已离开当前稿件');
      const ref=await uploadEditorMedia(output.projectId,outputId,file);if(!alive.current)throw new Error('已离开当前稿件');
      imported.current.set(`${ref.assetId}:${ref.assetFileId}`,{assetId:ref.assetId,assetFileId:ref.assetFileId});
      return {mediaId:`creatoros-asset:${ref.assetId}:${ref.assetFileId}`};
    }}/></div>
    <details className="text-xs text-muted-foreground"><summary className="cursor-pointer">开源来源与许可</summary><a className="underline" href="/reference-editors/sources/doocs-md/source.tar.gz" download>Doocs 对应源码与许可</a></details>
  </section>;
}

