 const [accountId,setAccountId]=React.useState<string|null>(null);
 React.useEffect(()=>setAccountId(readCurrentAccountId()),[]);useAccountsChanged(React.useCallback(()=>setAccountId(readCurrentAccountId()),[]));
 return <EditorContents key={`${accountId??'missing'}:${props.projectId}:${props.outputId??'empty'}`} {...props}/>;
}

