"use client";
import * as React from 'react';
import type {GraphicPostDocument,ReferenceEditorMedia} from '@creatoros/contract';
import {referenceEditorDocument} from '@creatoros/contract';
import {NativeEditorSurface,type NativeEditorHandle,type EditorSnapshot,type EditorExport} from './native-editor-surface';
import {uploadEditorMedia,hydrateGraphicDocument,freezeGraphicDocument,downloadEditorExport} from './reference-editor-media';
import {Button} from '@/components/ui/button';
import {Dialog,DialogContent,DialogTitle} from '@/components/ui/dialog';
type Design=NonNullable<GraphicPostDocument['designs']>[number];
export function GraphicDesignWorkbench({accountId,sourceVersionId,projectId,outputId,title,design,onSave,onClose}:{accountId:string;sourceVersionId:string;projectId:string;outputId:string;title:string;design:Design;onSave:(design:Design,image?:ReferenceEditorMedia)=>Promise<void>;onClose:()=>void}){
 const mountVersion=React.useRef(sourceVersionId);
 const pendingSave=React.useRef<{design:Design;image?:ReferenceEditorMedia;result?:EditorExport}|null>(null);
 const frame=React.useRef<NativeEditorHandle>(null),media=React.useRef<ReferenceEditorMedia[]>(design.document.mediaRefs),alive=React.useRef(true);
 const [busy,setBusy]=React.useState(false),[ready,setReady]=React.useState(false),[dirty,setDirty]=React.useState(false),[error,setError]=React.useState<string|null>(null),[message,setMessage]=React.useState<string|null>(null);
 const [closeConfirm,setCloseConfirm]=React.useState(false);const controller=React.useRef(new AbortController()),revoke=React.useRef<(()=>void)|null>(null);
 React.useEffect(()=>{alive.current=true;const abort=new AbortController();controller.current=abort;return()=>{alive.current=false;abort.abort();revoke.current?.();};},[]);
 async function load(){setBusy(true);try{const hydration=Object.keys(design.document.nativeDocument).length?await hydrateGraphicDocument(design.document,controller.current.signal):{document:null,revoke:()=>{}};revoke.current?.();revoke.current=hydration.revoke;if(!alive.current)return;await frame.current!.request('load',{document:hydration.document,title});if(alive.current){setReady(true);setDirty(false);}}catch(e){if(alive.current)setError(e instanceof Error?e.message:'原稿加载失败，请保留稿件后重试');}finally{if(alive.current)setBusy(false);}}
 async function save(exportImage:boolean){if(busy||!ready)return;setBusy(true);setError(null);try{
  // 保存回执未知时沿用同一份冻结稿和已上传文件，避免再导出/上传改变请求。
  if(!pendingSave.current){
   if(exportImage){const result=await frame.current!.request<EditorExport>('export',{format:'png'});if(!(result.blob instanceof Blob)||!result.blob.size||!result.document)throw Error('图片导出没有返回有效文件与对应图层');const document=referenceEditorDocument.parse(freezeGraphicDocument(result.document,media.current));pendingSave.current={design:{...design,document},result};downloadEditorExport(result.blob,result.fileName);}
   else{const snapshot=await frame.current!.request<EditorSnapshot>('snapshot');const document=referenceEditorDocument.parse(freezeGraphicDocument(snapshot.document,media.current));pendingSave.current={design:{...design,document}};}
  }
  const pending=pendingSave.current;
  if(pending.result&&!pending.image)pending.image=await uploadEditorMedia(projectId,outputId,new File([pending.result.blob],pending.result.fileName,{type:'image/png'}));
  if(!alive.current)return;await onSave(pending.design,pending.image);pendingSave.current=null;if(alive.current){setDirty(false);setMessage(pending.result?'图片已采用到当前稿件，图层也已保存。':'图层已保存，可以继续编辑。');}
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'保存未完成，当前图层已保留');}finally{if(alive.current)setBusy(false);}}
 return <Dialog open onOpenChange={open=>{if(!open&&!busy&&!pendingSave.current){if(dirty)setCloseConfirm(true);else onClose();}}}><DialogContent showCloseButton={false} aria-describedby={undefined} className="left-0 top-0 flex h-dvh w-screen max-w-none translate-x-0 translate-y-0 flex-col gap-0 rounded-none border-0 bg-background p-0 sm:max-w-none">
  <header className="flex flex-wrap items-center justify-between gap-3 border-b px-4 py-3"><div className="min-w-0"><DialogTitle className="truncate font-semibold">{title}</DialogTitle><p className="text-xs text-muted-foreground">{dirty?'有未保存修改':'文字、图片和图层均可直接编辑'}</p></div><div className="flex flex-wrap gap-2"><Button variant="outline" disabled={!ready||busy} onClick={()=>void save(false)}>保存设计</Button><Button disabled={!ready||busy} onClick={()=>void save(true)}>{busy?'处理中…':'导出并采用图片'}</Button><Button variant="ghost" disabled={busy||!!pendingSave.current} onClick={()=>dirty?setCloseConfirm(true):onClose()}>返回稿件</Button></div></header>
  {error&&<p role="alert" className="border-b p-3 text-sm text-destructive">{error}<button className="ml-3 underline" disabled={busy||!!pendingSave.current} onClick={()=>void load()}>重新读取原稿</button></p>}{message&&<p role="status" className="p-2 text-sm">{message}</p>}
  {closeConfirm&&<div className="flex flex-wrap items-center gap-3 border-b bg-surface-subtle p-3"><p>设计尚未保存。保存后可继续回到这张图。</p><Button disabled={busy} onClick={()=>void save(false).then(()=>setCloseConfirm(false))}>先保存设计</Button><Button variant="outline" onClick={()=>setCloseConfirm(false)}>继续编辑</Button><Button variant="ghost" disabled={busy||!!pendingSave.current} onClick={onClose}>放弃本次修改并返回</Button></div>}
  <details className="border-b px-4 py-2 text-xs text-muted-foreground"><summary className="cursor-pointer">开源来源与许可</summary><a href="/reference-editors/NOTICE.html" className="underline" target="_blank" rel="noreferrer">快图来源与许可</a></details>
  <div className="min-h-0 flex-1 overflow-hidden"><NativeEditorSurface ref={frame} editor="kuaitu" owner={{accountId,outputId,sourceVersionId:mountVersion.current}} disabled={busy||!!pendingSave.current} onReady={()=>void load()} onChanged={()=>{if(ready&&!busy)setDirty(true);}} onError={setError} onImport={async file=>{const ref=await uploadEditorMedia(projectId,outputId,file);if(!alive.current)throw Error('已离开当前稿件');media.current=[...media.current,ref];return{mediaId:ref.mediaId};}}/></div>
 </DialogContent></Dialog>;
}

'use client';
import * as React from 'react';
import type {NativeEditorHandle, NativeEditorOwner} from './native-editor-contract';
import {loadNativeEditor} from './native-editor-loader';
import {applyNativeEditorTheme, useNativeEditorTheme} from './native-editor-theme';
export type {EditorSnapshot, EditorExport, NativeEditorHandle} from './native-editor-contract';

type Props = {
  editor: 'kuaitu' | 'opencut-classic' | 'doocs-md' | 'noterelay';
  owner: NativeEditorOwner;
  disabled?: boolean;
  onReady(): void;
  onChanged(value?: unknown): void;
  onImport(file: File): Promise<{mediaId: string}>;
  onError(message: string): void;
};
/** 固定本地源码直接挂载；ShadowRoot 只隔离样式，业务正式稿由原作品服务持有。 */
export const NativeEditorSurface = React.forwardRef<NativeEditorHandle, Props>(function NativeEditorSurface(props, ref) {
  const host = React.useRef<HTMLDivElement>(null);
  const active = React.useRef<NativeEditorHandle | null>(null);
  const callbacks = React.useRef(props);
  const theme = useNativeEditorTheme();
  const latestTheme = React.useRef(theme);
  const [state, setState] = React.useState<'opening' | 'ready' | 'failed'>('opening');
  React.useLayoutEffect(() => {callbacks.current = props; latestTheme.current = theme;});
  React.useImperativeHandle(ref, () => ({
    request: async <T,>(operation: string, payload?: unknown, options?: {requestId?: string; signal?: AbortSignal}) => {
      const handle = active.current;
      if (!handle) throw new Error('编辑器尚未准备好');
      const result = await handle.request<T>(operation, payload, options);
      if (active.current !== handle) throw new Error('已切换作品，原操作停止');
      return result;
    },
    update: options => active.current?.update(options),
    dispose: async () => {const handle = active.current; active.current = null; await handle?.dispose();},
  }), []);
  const ownerKey = JSON.stringify(props.owner);
  React.useEffect(() => {
    if (!host.current || !latestTheme.current) return;
    const controller = new AbortController();
    const element = host.current;
    const shadow = element.shadowRoot ?? element.attachShadow({mode: 'open'});
    const container = document.createElement('div');
    const portals = document.createElement('div');
    container.style.cssText = 'height:100%;min-height:0;min-width:0;position:relative;overflow:hidden;';
    container.tabIndex = -1;
    portals.style.cssText = 'position:relative;z-index:60;';
    const css = document.createElement('link');
    css.rel = 'stylesheet'; css.href = `/reference-editors/${props.editor}/native/native.css`;
    const baseStyle = document.createElement('style');
    baseStyle.textContent = ':host{display:block;height:100%;min-height:0;color:var(--creatoros-text);background:var(--creatoros-surface);font-family:var(--creatoros-font-sans)}*,*::before,*::after{box-sizing:border-box}';
    let mounted: NativeEditorHandle | undefined;
    let cssResolve: () => void;
    let cssReject: (error: Error) => void;
    const cssReady = new Promise<void>((resolve, reject) => {cssResolve = resolve; cssReject = reject;});
    css.onload = () => cssResolve();
    css.onerror = () => cssReject(new Error('编辑器样式读取失败，请重新打开工作台'));
    const abortCss = () => cssReject(new Error('已离开当前作品'));
    controller.signal.addEventListener('abort', abortCss, {once: true});
    applyNativeEditorTheme(element, latestTheme.current);
    shadow.replaceChildren(baseStyle, css, container, portals);
    setState('opening');
    void (async () => {
      try {
        const [module] = await Promise.all([loadNativeEditor(props.editor), cssReady]);
        controller.signal.throwIfAborted();
        mounted = await module.mount(container, {
          owner: props.owner, theme: latestTheme.current!, portalContainer: portals, signal: controller.signal,
          onChanged: value => {if (!controller.signal.aborted) callbacks.current.onChanged(value);},
          onError: message => {if (!controller.signal.aborted) callbacks.current.onError(message);},
          importMedia: async file => {controller.signal.throwIfAborted(); const result = await callbacks.current.onImport(file); controller.signal.throwIfAborted(); return result;},
        });
        if (controller.signal.aborted) {await mounted.dispose(); return;}
        active.current = mounted;
        mounted.update({theme: latestTheme.current!, disabled: callbacks.current.disabled});
        setState('ready'); callbacks.current.onReady();
      } catch (error) {
        if (!controller.signal.aborted) {setState('failed'); callbacks.current.onError(error instanceof Error ? error.message : '编辑器没有完成加载');}
      }
    })();
    return () => {
      controller.abort();
      controller.signal.removeEventListener('abort', abortCss);
      if (active.current === mounted) active.current = null;
      void mounted?.dispose().catch(() => undefined);
