  <details className="text-xs text-muted-foreground"><summary className="cursor-pointer">开源来源与许可</summary><a className="underline" href="/reference-editors/NOTICE.html" target="_blank" rel="noreferrer">OpenCut 来源与许可</a></details>
  <div className="h-[min(780px,calc(100dvh-240px))] min-h-[440px] min-w-0 overflow-hidden rounded-xl border bg-surface">{accountId&&<NativeEditorSurface ref={frame} editor="opencut-classic" owner={{accountId,outputId:initial.outputId,sourceVersionId:mountVersion.current}} disabled={busy||aiBusy||!!saveRequest.current||!!pendingExport.current||!!pendingApply.current} onReady={()=>void load()} onChanged={()=>{if(ready&&!busyRef.current){dirtyRef.current=true;setDirty(true);setExported(null);}}} onError={setError} onImport={async file=>{const ref=await uploadEditorMedia(owner.projectId,owner.outputId,file);if(!alive.current)throw Error('已离开当前作品');media.current.push(ref);return{mediaId:ref.mediaId};}}/>}{!accountId&&<p className="p-4 text-sm text-muted-foreground">请先选择创作账号，再编辑当前作品。</p>}</div>
  {aiOpen&&<section aria-label="AI 辅助粗剪" className="min-w-0 space-y-3 rounded-lg border p-4"><div className="flex flex-wrap items-center gap-3"><h2 className="font-medium">AI 辅助粗剪</h2><Button size="sm" variant="outline" disabled={busy||aiBusy||!!pendingApply.current} onClick={()=>void refreshContext()}>读取时间轴选区</Button><p className="text-xs text-muted-foreground">先选主轨片段，保存后生成建议，再核对影响并采纳。独立图层保留原位置。</p></div><NativeSourcePanel key={owner.outputId} document={owner} media={media.current.filter(ref=>metadata.find(m=>m.mediaId===ref.mediaId)?.type==='video')} metadata={metadata} disabled={busy||aiBusy||!!pendingApply.current} prepareDocument={prepareDocument} onSaved={acceptVersion} onRecoverConflict={recoverConflict}/>{view&&nativeScope?<><ProductionTranscriptPanel document={owner} planView={view} disabled={busy||aiBusy||!!pendingApply.current} prepareDocument={prepareDocument} onSaved={acceptVersion} onRecoverConflict={recoverConflict} run={async action=>{setAiBusy(true);try{await action();}finally{if(alive.current)setAiBusy(false);}}}/><ProductionRoughCandidatePanel document={owner} planView={view} nativeScope={nativeScope} accountId={accountId} disabled={busy} prepareDocument={prepareDocument} onSaved={acceptVersion} onRecoverConflict={recoverConflict} onBusyChange={setAiBusy} onLocate={clipId=>{const e=nativeScope.scene.tracks.main.elements.find(e=>e.id===clipId);if(e)void frame.current!.request('seek',{outputId:owner.outputId,sceneId:nativeScope.sceneId,tick:e.startTime}).catch(error=>setError(error.message));}}/></>:<p className="text-sm text-muted-foreground">先将原视频放到主轨并登记原片信息，再读取时间轴选区。手工剪辑可继续使用。</p>}</section>}
  {exported&&<div className="flex flex-wrap items-center gap-3 rounded-lg border p-3"><p className="text-sm">{exported.fileName}</p>{delivery.hasExistingFinal&&<label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={delivery.replaceOk} onChange={e=>delivery.setReplaceOk(e.target.checked)}/>确认替换当前成片，旧文件保留在素材库</label>}<Button disabled={delivery.finalBusy||delivery.hasExistingFinal&&!delivery.replaceOk||delivery.pubLocked===true} onClick={()=>{if(delivery.hasExistingFinal&&!delivery.replaceOk)return;void delivery.onFinalFile(new File([exported.blob],exported.fileName,{type:'video/mp4'}));}}>{delivery.finalBusy?'正在采用…':'采用为作品成片'}</Button><Button variant="outline" onClick={()=>downloadEditorExport(exported.blob,exported.fileName)}>再次下载</Button>{delivery.finalError&&<p role="alert">{delivery.finalError}</p>}{delivery.finalNotice&&<p role="status">{delivery.finalNotice}</p>}</div>}
  {historyOpen&&<section className="rounded-lg border p-4" aria-label="历史剪辑工程"><h3 className="font-medium">历史版本</h3><p className="text-sm text-muted-foreground">恢复会创建新版本，原工程继续保留。</p>{history.map(row=><div key={row.revision} className="mt-2 flex items-center justify-between text-sm"><span>版本 {row.revision} · {new Date(row.createdAt).toLocaleString('zh-CN')}</span><Button size="sm" variant="outline" disabled={busy||aiBusy||dirty||!!saveRequest.current||!!pendingExport.current||!!pendingApply.current} onClick={()=>void restore(row.revision)}>恢复此版</Button></div>)}</section>}
 </section>;
}
